   .card {            border: none;            border-radius: 12px;            box-shadow: var(--card-shadow);            margin-bottom: 20px;            background: white;        }        .card-header {            background: white;            border-bottom: 1px solid rgba(0,0,0,0.08);            padding: 15px 20px;            border-radius: 12px 12px 0 0;        }        .card-body {            padding: 20px;        }        /* File Upload Styles */        .file-upload {            border: 2px dashed #e0e0e0;            border-radius: 12px;            padding: 30px;            text-align: center;            position: relative;            transition: all 0.3s ease;            background: #f8f9fa;            margin-bottom: 20px;        }        .file-upload.dragover {            border-color: var(--primary-color);            background: #f0f0f0;        }        .file-upload i {            font-size: 3rem;            color: #adb5bd;            margin-bottom: 15px;        }        .file-upload-input {            position: absolute;            top: 0;            left: 0;            width: 100%;            height: 100%;            opacity: 0;            cursor: pointer;        }        .selected-file {            margin-top: 10px;            font-size: 0.875rem;            color: #495057;        }        /* Button Styles */        .btn-primary {            background: var(--primary-color);            border-color: var(--primary-color);            padding: 10px 16px;            border-radius: 8px;            transition: all 0.3s ease;        }        .btn-primary:hover {            background: #43a047;            border-color: #43a047;            transform: translateY(-2px);            box-shadow: 0 4px 8px rgba(0,0,0,0.1);        }        .btn-outline-primary {            color: var(--primary-color);            border-color: var(--primary-color);            padding: 10px 16px;            border-radius: 8px;            transition: all 0.3s ease;        }        .btn-outline-primary:hover {            background: var(--primary-color);            color: white;            transform: translateY(-2px);            box-shadow: 0 4px 8px rgba(0,0,0,0.1);        }        /* Error message list */        .error-list {            max-height: 200px;            overflow-y: auto;            background: #f8f9fa;            border-radius: 8px;            padding: 10px;            margin-top: 15px;        }        .error-list ul {            padding-left: 20px;            margin-bottom: 0;        }        .error-list li {            color: var(--danger-color);            margin-bottom: 5px;        }        /* Responsive styles */        @media (max-width: 768px) {            .sidebar {                width: 60px;                padding-top: 50px;            }            .sidebar .nav-link span {                display: none;            }            .sidebar .nav-link {                padding: 12px;                margin: 4px 8px;                justify-content: center;            }            .top-navbar {                left: 60px;            }            .main-content {                margin-left: 60px;            }        }    </style></head><body><!-- Sidebar --><nav class="sidebar">    <ul class="nav flex-column">        <li class="nav-item">            <a class="nav-link" href="dashboard.php">                <i class="bi bi-speedometer2"></i>                <span>Dashboard</span>            </a>        </li>        <li class="nav-item">            <a class="nav-link" href="products_management.php">                <i class="bi bi-box"></i>                <span>Products</span>            </a>        </li>        <li class="nav-item">            <a class="nav-link" href="categories_groups.php?tab=categories">                <i class="bi bi-tags"></i>                <span>Categories</span>     