                    </ul>                </div>            <?php endif; ?>        <?php endif; ?>        <?php if ($successMessage): ?>            <div class="alert alert-success alert-dismissible fade show" role="alert">                <?php echo htmlspecialchars($successMessage); ?>                <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"></button>            </div>        <?php endif; ?>        <div class="row">            <!-- Import Section -->            <div class="col-md-6">                <div class="card">                    <div class="card-header">                        <h5 class="mb-0">Import Products</h5>                    </div>                    <div class="card-body">                        <p class="text-muted mb-4">                            Upload a CSV file to bulk import products. The file should include columns for product name,                            allergens, ingredients, health rating, recipe, image path, categories, and groups.                        </p>                        <form method="POST" enctype="multipart/form-data">                            <input type="hidden" name="action" value="import">                            <div class="file-upload" id="fileUploadArea">                                <i class="bi bi-cloud-arrow-up"></i>                                <h5>Drag & Drop CSV File</h5>                                <p class="text-muted">or click to browse files</p>                                <input type="file" name="csv_file" id="csvFileInput" class="file-upload-input" accept=".csv">                            </div>                            <div id="selectedFileName" class="selected-file d-none">                                Selected file: <span></span>                            </div>                            <div class="d-flex justify-content-between align-items-center">                                <a href="<?php echo $_SERVER['PHP_SELF']; ?>?action=download_template" class="btn btn-outline-primary">                                    <i class="bi bi-download"></i> Download Template                                </a>                                <button type="submit" class="btn btn-primary" id="importButton" disabled>                                    <i class="bi bi-upload"></i> Import Products                                </button>                            </div>                        </form>                    </div>                </div>            </div>            <!-- Export Section -->            <div class="col-md-6">                <div class="card">                    <div class="card-header">                        <h5 class="mb-0">Export Products</h5>                    </div>                    <div class="card-body">                        <p class="text-muted mb-4">                            Export all products to a CSV file. The file will include product details,                            categories, groups, and image paths.                        </p>                        <form method="POST">                            <input type="hidden" name="action" value="export">                            <div class="text-center py-4">                                <i class="bi bi-file-earmark-spreadsheet" style="font-size: 3rem; color: var(--primary-color);"></i>                                <h5 class="mt-3">Export All Products</h5>                                <p class="text-muted">Click the button below to download all products as a CSV file.</p>                            </div>                            <div class="d-flex justify-content-center">                                <button type="submit" class="btn btn-primary">                                    <i class="bi bi-download"></i> Export Products                                </button>                            </div>                        </form>                    </div>                </div>            </div>        </div>        <!-- Import Instructions -->        <div class="card mt-4">            <div class="card-header">                <h5 class="mb-0">Import Instructions</h5>            </div>            <div class="card-body">                <div class="alert alert-info">                    <i class="bi bi-info-circle-fill me-2"></i>                    <strong>CSV Formatting Tip:</strong> If you're seeing errors with your CSV file, please try saving it as "CSV UTF-8" format from Excel or your spreadsheet program. This helps prevent encoding issues.                </div>                                <h6>CSV File Format</h6>                <p>Your CSV file should contain the following columns:</p>                <div class="table-responsive">                    <table class="table table-striped">                        <thead>                        <tr>                            <th>Column</th>                            <th>Description</th>                            <th>Required</th>                        </tr>                        </thead>                        <tbody>                        <tr>                            <td>product_name</td>                            <td>The name of the product</td>                            <td><span class="badge bg-success">Yes</span></td>                        </tr>                        <tr>                            <td>allergens</td>                            <td>List of allergens in the product</td>                            <td><span class="badge bg-secondary">No</span></td>                        </tr>                        <tr>                            <td>ingredients</td>                            <td>Ingredients used in the product</td>                            <td><span class="badge bg-secondary">No</span></td>                        </tr>                        <tr>                            <td>healthy_option</td>                            <td>Health rating (Green, Amber, or Red)</td>                            <td><span class="badge bg-success">Yes</span></td>                        </tr>                        <tr>                            <td>recipe</td>                            <td>Recipe or preparation instructions</td>                            <td><span class="badge bg-secondary">No</span></td>                        </tr>                        <tr>                            <td>image_path</td>                            <td>Path to the product image (relative or absolute)</td>                            <td><span class="badge bg-secondary">No</span></td>                        </tr>                        <tr>                            <td>categories</td>                            <td>Comma-separated list of categories</td>                            <td><span class="badge bg-secondary">No</span></td>                        </tr>                        <tr>                            <td>groups</td>                            <td>Comma-separated list of groups</td>                            <td><span class="badge bg-secondary">No</span></td>                        </tr>                        </tbody>                    </table>                </div>                <h6>Handling Text Fields with Commas</h6>                <div class="alert alert-warning">                    <i class="bi bi-exclamation-triangle-fill me-2"></i>                    <strong>Important:</strong> When your ingredients, recipes, or other text fields contain commas, make sure they are enclosed in double quotes (" ") in your CSV file. Most spreadsheet applications will do this automatically when you save as CSV.                </div>                <p>Example of proper CSV format with quoted fields:</p>                <pre class="bg-light p-3 border rounded">product_name,ingredients,healthy_option"Veggie Pizza","Flour, Tomato Sauce, Cheese, Bell Peppers, Onions, Olives",Green</pre>                <h6>Image Handling</h6>                <p>For image_path, you can use:</p>                <ul>                    <li><strong>Existing Images:</strong> Provide the filename of an image that's already in the uploads directory.</li>                    <li><strong>New Images:</strong> Provide an absolute path to an image on the server, and it will be copied to the uploads directory.</li>                    <li><strong>No Image:</strong> Leave blank if there's no image for the product.</li>                </ul>                <h6>Categories and Groups</h6>                <p>                    For categories and groups, provide lists of values separated by commas. These will be split into individual categories/groups.                    If a category or group doesn't exist, it will be created automatically.                </p>                <h6>Health Rating</h6>                <p>                    The health rating must be one of the following values: Green, Amber, or Red.                    Any other value will cause the import of that row to fail.                </p>                                <div class="alert alert-info">                    <i class="bi bi-info-circle-fill me-2"></i>                    <strong>Tip:</strong> Use the template provided by the "Download Template" button to ensure your CSV file is properly formatted. When editing in Excel or other spreadsheet software, save as "CSV UTF-8" format for best results.                </div>            </div>        </div>    </div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js"></script><script>    // File Upload Handling    const fileInput = document.getElementById('csvFileInput');    const fileUploadArea = document.getElementById('fileUploadArea');    const selectedFileName = document.getElementById('selectedFileName');    const importButton = document.getElementById('importButton');    // Handle file selection    fileInput.addEventListener('change', function(e) {        const file = e.target.files[0];        if (file) {            selectedFileName.querySelector('span').textContent = file.name;            selectedFileName.classList.remove('d-none');            importButton.disabled = false;                        // Validate file extension            const fileExt = file.name.split('.').pop().toLowerCase();            if (fileExt !== 'csv') {                alert('Only CSV files are allowed.');                fileInput.value = '';                selectedFileName.classList.add('d-none');                importButton.disabled = true;            }        } else {            selectedFileName.classList.add('d-none');            importButton.disabled = true;        }    });    // Drag and drop functionality    ['dragenter', 'dragover', 'dragleave', 'drop'].forEach(eventName => {        fileUploadArea.addEventListener(eventName, preventDefaults, false);    });    function preventDefaults(e) {        e.preventDefault();        e.stopPropagation();    }    ['dragenter', 'dragover'].forEach(eventName => {        fileUploadArea.addEventListener(eventName, highlight, false);    });    ['dragleave', 'drop'].forEach(eventName => {        fileUploadArea.addEventListener(eventName, unhighlight, false);    });    function highlight() {        fileUploadArea.classList.add('dragover');    }    function unhighlight() {        fileUploadArea.classList.remove('dragover');    }    fileUploadArea.addEventListener('drop', handleDrop, false);    function handleDrop(e) {        const dt = e.dataTransfer;        const files = dt.files;        fileInput.files = files;                // Trigger change event        const event = new Event('change');        fileInput.dispatchEvent(event);    }    // Responsive sidebar toggle    document.addEventListener('DOMContentLoaded', function() {        const mediaQuery = window.matchMedia('(max-width: 768px)');        function handleScreenChange(e) {            if (e.matches) {                document.querySelector('.sidebar').classList.add('collapsed');                document.querySelector('.main-content').classList.add('expanded');            } else {                document.querySelector('.sidebar').classList.remove('collapsed');                document.querySelector('.main-content').classList.remove('expanded');            }        }        mediaQuery.addListener(handleScreenChange);        handleScreenChange(mediaQuery);    });</script></body></html>